/// <summary>
/// On deleted event handler for METWHSPhysDimUOMSite datasource
/// </summary>
/// <param name="sender">Form data source</param>
/// <param name="e">Event args</param>
[FormDataSourceEventHandler(formDataSourceStr(MetWHSPhysDimUOMSite, METWHSPhysDimUOMSiteData), FormDataSourceEventType::Deleted),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void METWHSPhysDimUOMSiteData_OnDeleted(FormDataSource sender, FormDataSourceEventArgs e)
{
    if(sender.formRun() && formHasMethod(sender.formRun(), identifierStr(refreshInventSiteDataSource)))
    {
        FormRun fr = sender.formRun() as FormRun;
        fr.refreshInventSiteDataSource();
    }
}

/// <summary>
/// On written event handler for METWHSPhysDimUOMSite datasource
/// </summary>
/// <param name="sender">Form data source</param>
/// <param name="e">Event args</param>
[FormDataSourceEventHandler(formDataSourceStr(MetWHSPhysDimUOMSite, METWHSPhysDimUOMSiteData), FormDataSourceEventType::Written),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void METWHSPhysDimUOMSiteData_OnWritten(FormDataSource sender, FormDataSourceEventArgs e)
{
    if(sender.formRun() && formHasMethod(sender.formRun(), identifierStr(refreshInventSiteDataSource)))
    {
        FormRun fr = sender.formRun() as FormRun;
        fr.refreshInventSiteDataSource();
    }
}
